def pre(vals, sep):
    return -9 <= sep <= 9 and all(-9 <= v <= 9 for v in vals) and len(vals) <= 5

def post(vals, sep, result):
    if not isinstance(result, list) or len(result) != len(vals) + len(vals) - 1:
        return False
    for i in range(len(result)):
        if i == 0 and result[i] != sep:
            return False
        elif (i > 0 and i < len(result) - 1 and 
              (result[i-1] not in vals or result[i+1] not in vals)):
            return False
    return True

def is_in_list(val, lst):
    return any(v == val for v in lst)

def is_consecutive(i, j, lst):
    return i < len(lst) and j < len(lst) and abs(j - i) == 1 and all(is_in_list(l, lst[i:j]) or l == sep for l in lst[i+1:j])
